A \emph{pre-realization} of a Coxeter group $(W,S)$ over $\mathbbm{k}$ consists of a free, finite rank $\mathbbm{k}$-module $\mathfrak{h}$ along with subsets
                \[\{\alpha_s^{\vee} : s \in S\} \subset \mathfrak{h} \qquad\text{and}\qquad \{\alpha_s : s\in S\} \subset \mathfrak{h}^*,\]
                called the simple coroots and simple roots respectively, such that
                \begin{enumerate}
                        \item $\langle \alpha_s^{\vee}, \alpha_s \rangle = 2$ for all $s \in S$;
                        \item the assignment
                                \[s (v) = v - \langle v , \alpha_s \rangle \alpha_s^{\vee}\]
                                for all $s \in S$ and $v \in \mathfrak{h}$ defines a representation of $W$ on $\mathfrak{h}$;
                        \item $\alpha_s : \mathfrak{h} \to \mathbbm{k}$ and $\alpha_s^{\vee}: \mathfrak{h}^* \to \mathbbm{k}$ are surjective for all $s \in S$.
                \end{enumerate}

                To every pre-realization $\mathfrak{h}$, there is a Cartan matrix $[a_{st}]_{s,t \in S}$ where $a_{st} \coloneq \langle \alpha_s^{\vee}, \alpha_t \rangle$.
                We will further call $\mathfrak{h}$ a \emph{realization} if for all distinct $s,t \in S$ such that $st$ has order $m_{st} < \infty$, we have
                \begin{equation}\label{eq:qbinom_vanishing}
                         \genfrac{[}{]}{0pt}{}{m_{st}}{k}_x (-a_{st}, -a_{ts})  = \genfrac{[}{]}{0pt}{}{m_{st}}{k}_y  (-a_{st}, -a_{ts})  = 0
                \end{equation}
                for all integers $1 \leq k \leq m_{st} - 1$.

Let $(W,S)$ be a Coxeter group with realization $\mathfrak{h}$ over $\mathbbm{k}$. We say that $\mathfrak{h}$ is \emph{balanced} if 
                \begin{equation}\label{eq:balanced}
                        [m_{st} - 1]_x (-a_{st}, -a_{ts}) = 1 = [m_{st} - 1]_y (-a_{st}, -a_{ts})
                \end{equation}
                for all distinct $s,t \in S$ with $m_{st} < \infty$.

\label{thm:abe_conditions}
                Let $s,t \in S$ be distinct simple reflections with $m = m_{st} < \infty$ and $m > 2$.
                \begin{enumerate}
                        \item If $m$ is odd, then \eqref{eq:qbinom_vanishing} and \eqref{eq:balanced} hold if and only if $a_{st} = a_{ts}$ and $\Psi_m' (-a_{st}) = 0$.
                        \item If $m$ is even, then \eqref{eq:qbinom_vanishing} and \eqref{eq:balanced} hold if and only if $\Psi_m (a_{st} a_{ts}) = 0$.
                \end{enumerate}

\label{lem:root_about_refln}
                Let $(W,S)$ be a Coxeter group with a balanced realization $\mathfrak{h}$. Let $r$ be a reflection in $W$.
                Assume that $r = xsx^{-1} = yty^{-1}$ for some $x,y \in W$ and $s,t \in S$ such that $xs > x$ and $yt > y$. Then $x \alpha_s = y \alpha_t$.

\label{prop:bases_of_BS}
        Let $\underline{w} \in \operatorname{Exp} (W)$ and $x \in W$.
        \begin{enumerate}
                \item The set $\{ t_{\underline{w}, \mathbf{e}} \}_{\mathbf{e} \in \operatorname{Sub} (\underline{w})}$ forms a left $R$-module basis of $B_{\underline{w}}$.
                \item The set $\{ b_{\underline{w}, \mathbf{e}}^x\}_{\mathbf{e} \in \operatorname{Sub}^x (\underline{w})}$ forms a left $R$-module basis of $B_{\underline{w}}^x$.
        \end{enumerate}

\label{lem:decomp_into_loc_pieces}
        Let $\underline{w} \in \operatorname{Exp} (W)$. There is a decomposition of graded $Q$-bimodules,
        \[B_{\underline{w}} \otimes_R Q \cong \bigoplus_{\mathbf{e} \in \operatorname{Sub} (\underline{w})} B_{\underline{w}, Q}^{\mathbf{e}} \cong \bigoplus_{\mathbf{e} \in \operatorname{Sub} (\underline{w})} Q_{\underline{w}^{\mathbf{e}}} (-\ell (\underline{w})).\]

An $\operatorname{LL}$-datum is a triple $(\operatorname{rex}, \{\operatorname{rex}_s\}_{s \in S}, \{p_{\underline{x}, \underline{y}}\}_{\underline{x}, \underline{y}})$ consisting of the following:
                \begin{enumerate}
                        \item a map $\operatorname{rex} : W \to \operatorname{Exp} (W)$ such that for each $x \in W$, $\operatorname{rex} (x)$ is a reduced expression for $x$;
                        \item for each $s \in S$, a map $\operatorname{rex}_s : \mathcal{R}_s \to \operatorname{Exp} (W)$ where $\mathcal{R}_s = \{w \in W \mid ws < w\}$ and $\operatorname{rex}_s (x)$ is a reduced expression for $x$ ending in $s$;
                        \item for any two rexes $\underline{x}$ and $\underline{y}$ of $x$, a path $p_{\underline{x}, \underline{y}}$ from $\underline{x}$ to $\underline{y}$ in the rex graph of $x$.
                \end{enumerate}

\label{cor:BS_inj_or_surj}
        Let $(\sigma, f) : \mathfrak{h} \to \mathfrak{h}'$ be a morphism of realizations.
        \begin{enumerate}
                \item $f : R_\mathfrak{h} \to R_{\mathfrak{h}'}$ is injective if and only if $\mathsf{ABS}_f$ is faithful.
                \item $f : R_{\mathfrak{h}} \to R_{\mathfrak{h}'}$ is surjective if and only if $\mathsf{ABS}_f$ is full.
        \end{enumerate}

