\label{lem:loc_mat_of_dual}
                Let $\varphi : B_{\underline{x}} \to B_{\underline{y}}$, $\mathbf{e} \in \operatorname{Sub} (\underline{x})$, and $\mathbf{f} \in \operatorname{Sub} (\underline{y})$. 
                Then
                \begin{equation}\label{eq:loc_mat_of_dual_0}
                        \Lambda (\mathbb{D} (\varphi)) = \Lambda (\varphi)^\dagger .
                \end{equation}
                In particular,
                \[\Lambda (\mathbb{D} (\varphi))_{\mathbf{e}, \mathbf{f}} = \frac{\zeta_{\underline{y}} (\mathbf{f})}{\zeta_{\underline{x}} (\mathbf{e})} \Lambda (\varphi)_{\mathbf{f}, \mathbf{e}}. \]

\label{prop:loc_of_dl}
                Let $\underline{x}, \underline{y} \in \operatorname{Exp} (W)$ and $\mathbf{e} \in \operatorname{Sub} (\underline{x})$, $\mathbf{f} \in \operatorname{Sub} (\underline{y})$ such that $\underline{x}^{\mathbf{e}} = w = \underline{y}^{\mathbf{f}}$. Then
                \[\Lambda (\mathbb{L}\mathbb{L}_{\mathbf{e}, \mathbf{f}}^w)_{\mathbf{r}, \mathbf{c}} = \frac{1}{\zeta_{\underline{y}} (\mathbf{r})} \sum_{\mathbf{h} \in \operatorname{Sub} (\operatorname{rex} (w))} \zeta_{\operatorname{rex} (w)} (\mathbf{h}) (\Lambda (\operatorname{LL}_{\underline{y}, \mathbf{f}})_{\mathbf{h}, \mathbf{r}} ) \Lambda (\operatorname{LL}_{\underline{x}, \mathbf{e}})_{\mathbf{h}, \mathbf{c}}.\]

\label{thm:lower_triang_of_coord_functionals}
                If $\lambda_i (\mathbb{L}\mathbb{L}_j) \neq 0$, then $j \leq i$. Moreover,
                \begin{equation}\label{eq:lower_triang_of_coord_functionals_0}
                \lambda_i (\mathbb{L}\mathbb{L}_i) = \frac{\zeta_{\operatorname{rex} (w_i)} (\mathbf{1})}{\zeta_{\underline{y}} (\mathbf{f}^i)} \gamma_{\underline{x}} (\mathbf{e}^i) \gamma_{\underline{y}} (\mathbf{f}^i) \in Q^{\times}.
                \end{equation}

\label{cor:recursion_for_coeffs}
                Let $\varphi : B_{\underline{x}} \to B_{\underline{y}}$. We can write
                \begin{equation}\label{eq:recursion_for_coeffs_1}
                        \varphi = \sum_{i=1}^N c_i \mathbb{L}\mathbb{L}_i
                \end{equation}
                for some $c_i \in R$. Then
                \begin{equation}\label{eq:recursion_for_coeffs_2}
                        c_i = \frac{\lambda_i (\varphi) - \sum_{j < i} c_j \lambda_i (\mathbb{L}\mathbb{L}_j)}{\lambda_i (\mathbb{L}\mathbb{L}_i)}.
                \end{equation}

\label{cor:eq_testing}
                Let $\varphi, \psi : B_{\underline{x}} \to B_{\underline{y}}$ be two morphisms of Abe--Bott--Samelson bimodules.
                Then $\varphi = \psi$ if and only if $\lambda_i (\varphi) = \lambda_i (\psi)$ for all $i=1,\ldots, N$.

\label{algo:coeff_algo}
                Let $\varphi : B_{\underline{x}} \to B_{\underline{y}}$ be a morphism of Abe--Bott--Samelson bimodules of homogeneous degree $d$.

                Consider the collection of double leaves from $B_{\underline{x}}$ to $B_{\underline{y}}$ of degree $\leq d$ and such that the degree has the same parity as $d$.
                Enumerate this collection by $\mathbb{L}\mathbb{L}_1, \mathbb{L}\mathbb{L}_2, \ldots, \mathbb{L}\mathbb{L}_{N_d}$ where $\mathbb{L}\mathbb{L}_i = \mathbb{L}\mathbb{L}_{\mathbf{e}^i, \mathbf{f}^i}^{w_i}$ such that 
                \begin{enumerate}[label=(\alph*)]
                        \item for $i < j$, then $\ell (w_j) \leq \ell (w_i)$;
                        \item for $i < j$ and $\ell (w_i) = \ell (w_j)$, then $h_{\underline{x}} (\mathbf{e}^j) + h_{\underline{y}} (\mathbf{f}^j) \leq  h_{\underline{x}} (\mathbf{e}^i) + h_{\underline{y}} (\mathbf{f}^i)$.
                \end{enumerate}
                Any enumeration satisfying (a) and (b) is allowed.

                Write
                \[\varphi = \sum_{i=1}^{N_d} c_i \mathbb{L}\mathbb{L}_i\]
                for some $c_i \in R$. 
                \begin{enumerate}   
                        \item If $N_d = 0$, then $\varphi = 0$, so we may assume that $N_d > 0$.   
                        \item For $i=1, \ldots, N_d$, we solve  the coefficients $c_i$ as follows:
                        \[c_i = \frac{\lambda_i (\varphi) - \sum_{j < i} c_j \lambda_i (\mathbb{L}\mathbb{L}_j)}{\lambda_i (\mathbb{L}\mathbb{L}_i)}.\]
                        The terms appearing on the right-hand side can be computed as needed:
                        \begin{enumerate}
                                \item Compute the terms $\lambda_i (\varphi) = \Lambda (\varphi)_{\mathbf{f}^i, \mathbf{e}^i}$ using the observations from \S\ref{ss:entries_of_loc_mat}.
                                \item For the diagonal entries, 
                                \begin{equation}\label{eq:coeff_algo_1}
                                 \lambda_i (\mathbb{L}\mathbb{L}_i) = \frac{\zeta_{\operatorname{rex}(w_i)} (\mathbf{1})}{\zeta_{\underline{y}} (\mathbf{f}^i)} \gamma_{\underline{x}} (\mathbf{e}^i) \gamma_{\underline{y}} (\mathbf{f}^i).
                                \end{equation}
                                 \item For $j < i$, we only need to compute $\lambda_i (\mathbb{L}\mathbb{L}_j)$ when $c_j \neq 0$. In this case, we compute these values by the equation
                                 \begin{equation}\label{eq:coeff_algo_2}
                                 \lambda_i (\mathbb{L}\mathbb{L}_j) = \frac{1}{\zeta_{\underline{y}} (\mathbf{f}^i)} \sum_{\mathbf{h} \in \operatorname{Sub} (\operatorname{rex} (w_j))} \zeta_{\operatorname{rex} (w_j)} (\mathbf{h}) (\Lambda (\operatorname{LL}_{\underline{y}, \mathbf{f}^j})_{\mathbf{h}, \mathbf{f}^i}) (\Lambda (\operatorname{LL}_{\underline{x}, \mathbf{e}^j})_{\mathbf{h}, \mathbf{e}^i}).
                                 \end{equation}
                                 This amounts to computing a weighted dot product of the $\mathbf{f}^i$-column vector of $\Lambda (\operatorname{LL}_{\underline{y}, \mathbf{f}^j})$ and the $\mathbf{e}^i$-column vector of $\Lambda (\operatorname{LL}_{\underline{x}, \mathbf{e}^j})$.
                                 These columns of the localization matrix can be computed as needed using the observations from \S\ref{ss:entries_of_loc_mat}. Some extra details on speeding up this computation are given in Remark~\ref{rem:computing_dll_coeffs} below.
                        \end{enumerate}
                        \item After $i$ has been iterated from $1$ to $N_d$, all coefficients $c_1, \ldots, c_{N_d}$ have been calculated.
                \end{enumerate}

\label{prop:interpolation}
                Let $\tilde{a} \in \mathbb{Z}_{\geq 0}^n$.
                \begin{enumerate}
                        \item There is an isomorphism of vector spaces
                        \[\operatorname{ev}_d^{\tilde{a}} : A_n^{\leq d} \stackrel{\sim}{\to} \operatorname{Fun} (X_d^{\tilde{a}}, \mathbbm{k}), \qquad p \mapsto (a \mapsto p (a)).\]
                        \item For a function $\mu : X_d^{\tilde{a}} \to \mathbbm{k}$, we set
                        \[b_{a}^{\tilde{a}} (\mu) = \sum_{b \leq a} (-1)^{\lvert a \rvert - \lvert b \rvert} \binom{a}{b} \mu (\tilde{a} + b),\]
                        Then
                        \begin{equation}\label{eq:interpolation_1}
                        (\operatorname{ev}_d^{\tilde{a}})^{-1} (\mu) (x_1, \ldots, x_n) = \sum_{a \in L_d} b_{a}^{\tilde{a}} (\mu) B_{a}^{\tilde{a}}.
                        \end{equation}
                \end{enumerate}

\label{algo:coeff_algo_interpolate}
                Assume that $\Phi$ is finite.
                Let $\varphi : B_{\underline{x}} \to B_{\underline{y}}$ be a morphism of Abe--Bott--Samelson bimodules of homogeneous degree $d$. 

                Consider the collection of double leaves from $B_{\underline{x}}$ to $B_{\underline{y}}$ of degree $\leq d$ and such that the degree has the same parity as $d$.
                Enumerate this collection by $\mathbb{L}\mathbb{L}_1, \mathbb{L}\mathbb{L}_2, \ldots, \mathbb{L}\mathbb{L}_{N_d}$ where $\mathbb{L}\mathbb{L}_i = \mathbb{L}\mathbb{L}_{\mathbf{e}^i, \mathbf{f}^i}^{w_i}$ such that
                \begin{enumerate}[label=(\alph*)]
                        \item for $i < j$, then $\ell (w_j) \leq \ell (w_i)$;
                        \item for $i < j$ and $\ell (w_i) = \ell (w_j)$, then $h_{\underline{x}} (\mathbf{e}^j) + h_{\underline{y}} (\mathbf{f}^j) \leq  h_{\underline{x}} (\mathbf{e}^i) + h_{\underline{y}} (\mathbf{f}^i)$.
                \end{enumerate}
                Any enumeration satisfying (a) and (b) is allowed. We set $d_i$ to be the degree of $\mathbb{L}\mathbb{L}_i$. Define $k_i = (d-d_i)/2$.

                Write
                \[\varphi = \sum_{i=1}^{N_d} c_i  \mathbb{L}\mathbb{L}_i\]
                for some $c_i \in R^{d-d_i}$ which under the trivialization \eqref{eq:triv_of_R} is viewed as a homogeneous polynomial of degree $k_i$ in the variables $x_1, \ldots, x_r$.

                \begin{enumerate}
                        \item If $N_d = 0$, then $\varphi = 0$. Otherwise, define $K = \max_{i=1,\ldots, N_d} k_i$ and pick some $K$-regular shift $\tilde{a}$. By convention, we define $Y_{-1}^{\tilde{a}} = \varnothing$.
                        \item For $k=0, 1, \ldots, K$, perform the following steps:
                        \begin{enumerate}
                            \item For each $a \in Y_k^{\tilde{a}} \setminus Y_{k-1}^{\tilde{a}}$, we induct on $i=1,\ldots, N_d$. At each index $i$, we solve for $c_i (a)$ as follows.
                            \begin{enumerate}
                                \item If $k_i < k$, the polynomial $c_i (x_1, \ldots, x_r)$ is already determined by interpolation. We compute $c_i (a)$ then by evaluating this known polynomial.
                                \item If $k_i \geq k$, we compute $c_i (a)$ by the equation
                                \begin{equation}\label{eq:coeff_algo_interpolate_1}
                                    c_i (a) = \frac{\lambda_i (\varphi) (a) - \sum_{j < i} c_j (a) \lambda_i (\mathbb{L}\mathbb{L}_j) (a)}{\lambda_i (\mathbb{L}\mathbb{L}_i) (a)}.
                                \end{equation}
                                If $c_j (a) = 0$ for $j < i$, we skip computing $\lambda_i (\mathbb{L}\mathbb{L}_j) (a)$. If $c_j (a) \neq 0$, then $\lambda_i (\mathbb{L}\mathbb{L}_j) (a)$ can be computed from \eqref{eq:coeff_algo_2}, but evaluated at the point $a$ (see also Remark~\ref{rem:computing_dll_coeffs}).
                                The columns of the localization matrices are not computed symbolically in $Q$, but instead, we work only with terms in $\mathbbm{k}$ after applying the evaluation morphism $R \to \mathbbm{k}$ at the point $a$.  
                                The value $\lambda_i (\mathbb{L}\mathbb{L}_i) (a)$ is computed from \eqref{eq:coeff_algo_1}, but likewise at the point $a$ instead of symbolically.
                            \end{enumerate}
                            \item After all points of $Y_k \setminus Y_{k-1}$ are iterated through, we can reconstruct the homogeneous polynomials $c_i$ of degree $k_i = k$ from their values at the points of $Y_{k}^{\tilde{a}}$ using Corollary~\ref{cor:homog_interpolation}.
                            Store this polynomial for later steps.
                        \end{enumerate}
                        \item After $k$ is iterated from $0$ to $K$, all polynomials $c_1, \ldots, c_{N_d}$ have been constructed.
                \end{enumerate}

Let $\mathfrak{h}$ be a balanced realization for $W$ over a noetherian domain $\mathbbm{k}$. 
                An \emph{integral model} for $\mathfrak{h}$ consists of the following:
                \begin{enumerate}
                 \item a characteristic-zero integral domain $\mathcal{Z}$ that is finitely generated as a $\mathbb{Z}$-algebra;
                \item a balanced realization $\mathfrak{h}_{\mathcal{Z}}$ over $\mathcal{Z}$;
                \item a morphism of realizations $(\sigma, f) : \mathfrak{h}_{\mathcal{Z}} \to \mathfrak{h}$.
                \end{enumerate}

\label{lem:universal_H3_realization}
                Let $W = H_3$. There exists a balanced realization $\mathfrak{h}_{\mathcal{Z}}$ over $\mathcal{Z} = \mathbb{Z}[\tau]/(\tau^2-\tau-1)$ such that $\mathfrak{h}_{\mathcal{Z}}$ is an integral model for any balanced realization $\mathfrak{h}$ of $W$.
                Moreover, $\mathbb{Q} (\phi) \cong \operatorname{Frac} (\mathcal{Z})$, and as a result, the base change of $\mathfrak{h}_{\mathcal{Z}}$ to $\mathbb{Q} (\phi)$ is isomorphic to the golden realization $\mathfrak{h}_{\mathbb{Q} (\phi)}$.

